{"implementation":"def solve(case):
    segments = case["segments"]
    budget = case["budget"]
    allocations = [min(s["minimum"], s["capacity"]) for s in segments]
    remaining = max(0, budget - sum(allocations))

    while remaining:
        eligible = [i for i, s in enumerate(segments) if allocations[i] < s["capacity"]]
        if not eligible:
            break
        weight_total = sum(max(0, segments[i]["importance"]) for i in eligible)
        if weight_total == 0:
            for i in eligible:
                if remaining == 0:
                    break
                allocations[i] += 1
                remaining -= 1
            continue

        shares = {i: remaining * max(0, segments[i]["importance"]) / weight_total for i in eligible}
        added = 0
        for i in eligible:
            amount = min(segments[i]["capacity"] - allocations[i], int(shares[i]))
            if amount:
                allocations[i] += amount
                added += amount
        remaining -= added
        if remaining == 0:
            break

        ranked = sorted(
            (i for i in eligible if allocations[i] < segments[i]["capacity"]),
            key=lambda i: (shares[i] - int(shares[i]), segments[i]["importance"], -i),
            reverse=True,
        )
        if not ranked:
            continue
        for i in ranked:
            if remaining == 0:
                break
            if allocations[i] < segments[i]["capacity"]:
                allocations[i] += 1
                remaining -= 1

    return {
        "allocations": allocations,
        "by_name": {s["name"]: allocations[i] for i, s in enumerate(segments)},
        "total": sum(allocations),
    }
"}
